test_cases.assertion_pseudocode:
import glob, os
agent_fox_dir = 'packages/agentfox/agentfox/'
SDK_CONTAINMENT = {'claude_agent_sdk': 'claude.py'}
all_files = glob.glob(os.path.join(agent_fox_dir, '**', '*.py'), recursive=True)
assert len(all_files) > 0, 'No Python files found — check agent_fox_dir path'
for sdk_name, allowed_filename in SDK_CONTAINMENT.items():
    for filepath in all_files:
        if os.path.basename(filepath) == allowed_filename:
            continue  # skip the designated file
        with open(filepath, 'r') as f:
            contents = f.read()
        assert sdk_name not in contents, \
            f'SDK "{sdk_name}" found in non-designated file: {filepath}'

property_tests.invariant_check:
from hypothesis import given, strategies as st
from agentfox.session.backends import create_backend, Backend
from agentfox.core.errors import ConfigError

@given(name=st.one_of(st.just('claude'), st.text(min_size=0, max_size=50), st.just('')))
def test_create_backend_invariant(name):
    try:
        result = create_backend(name)
        # Must return a Backend or raise ConfigError — nothing else
        assert isinstance(result, Backend), f'Result is not a Backend: {type(result)}'
    except ConfigError:
        pass  # expected for invalid names
    except Exception as e:
        raise AssertionError(f'Unexpected exception type {type(e)}: {e}')

import glob, os
agent_fox_dir = 'packages/agentfox/agentfox/'
SDK_CONTAINMENT = {'claude_agent_sdk': 'claude.py'}
all_files = glob.glob(os.path.join(agent_fox_dir, '**', '*.py'), recursive=True)
assert len(all_files) > 0, f'No files found in {agent_fox_dir}'
for sdk_name, allowed_filename in SDK_CONTAINMENT.items():
    for filepath in all_files:
        if os.path.basename(filepath) == allowed_filename:
            continue
        with open(filepath, 'r', encoding='utf-8') as f:
            contents = f.read()
        assert sdk_name not in contents, \
            f'SDK containment violation: "{sdk_name}" found in {filepath}'

edge_case_tests.assertion_pseudocode:
from agentfox.session.backends import create_backend
from agentfox.core.errors import ConfigError
try:
    create_backend('')
    assert False, 'Expected ConfigError for empty string'
except ConfigError as e:
    assert 'Unknown backend' in str(e) or "''" in str(e)
    # Same code path as for 'foo'
try:
    create_backend('foo')
except ConfigError as e2:
    # Both should be ConfigError, not ValueError or other type
    pass
